    #     if "final_answer" in turn:
    #         return turn["final_answer"], len(messages)
    #     result = dispatch(turn["tool_call"], TOOLS)
    #     messages.append({"role": "tool", "content": str(result)})
    return "stopped: step limit reached", len(messages)

model = ScriptedModel([
    {"tool_call": {"name": "add", "args": {"a": 20, "b": 22}}},
    {"tool_call": {"name": "shout", "args": {"text": "forty-two"}}},
    {"final_answer": "FORTY-TWO!"},
])
answer, n = run_agent(model, "Add 20 and 22, then shout it.")
